 const ticks=(lo<0?[lo,0,hi]:[0,hi/2,hi]).map(v=>`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" class="${v===0&&lo<0?'zero':'grid'}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${fmt(v,unit)}</text>`).join('');
